-- Verificação posterior da Migration 011; diagnóstica inclusive em execução parcial.
SELECT VERSION() AS mysql_version;
SET @docmotor_verify_sql = IF(EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'schema_migrations'), 'SELECT COUNT(*) AS migration_011_count FROM __DOCMOTOR_DATABASE__.schema_migrations WHERE name = ''011_suspension_form_usability.sql''', 'SELECT CAST(NULL AS UNSIGNED) AS migration_011_count');
PREPARE docmotor_verify_stmt FROM @docmotor_verify_sql; EXECUTE docmotor_verify_stmt; DEALLOCATE PREPARE docmotor_verify_stmt;
SELECT f.field_key, f.label FROM __DOCMOTOR_DATABASE__.service_form_fields f JOIN __DOCMOTOR_DATABASE__.service_versions v ON v.id = f.service_version_id JOIN __DOCMOTOR_DATABASE__.services s ON s.id = v.service_id WHERE s.code = 'LOWERED_SUSPENSION' AND f.field_key IN ('suspension.contact_check','wheels.contact_check','suspension.clearance_check','wheels.fender_check','wheels.diameter_check') ORDER BY f.field_key;
SELECT f.field_key, o.option_value, o.option_label FROM __DOCMOTOR_DATABASE__.service_field_options o JOIN __DOCMOTOR_DATABASE__.service_form_fields f ON f.id = o.field_id JOIN __DOCMOTOR_DATABASE__.service_versions v ON v.id = f.service_version_id JOIN __DOCMOTOR_DATABASE__.services s ON s.id = v.service_id WHERE s.code = 'LOWERED_SUSPENSION' AND f.field_key IN ('suspension.contact_check','wheels.contact_check','suspension.clearance_check','wheels.fender_check','wheels.diameter_check') ORDER BY f.field_key, o.display_order;
SELECT COUNT(*) AS other_state_manual_rules FROM __DOCMOTOR_DATABASE__.technical_rules r JOIN __DOCMOTOR_DATABASE__.services s ON s.id = r.service_id WHERE s.code = 'LOWERED_SUSPENSION' AND r.id = '5A000000-0000-4000-8000-000000000008' AND r.expected_result = 'MANUAL_REVIEW' AND r.priority = 1;
SELECT COUNT(*) AS duplicate_migration_rows FROM __DOCMOTOR_DATABASE__.schema_migrations WHERE name = '011_suspension_form_usability.sql';
